e("antiinfective", "Antivirals", "مضادات الفيروسات", "Valacyclovir", "فالاسيكلوفير", "J05AB11",
  "طليعة دواء للآسيكلوفير بامتصاص أفضل وجرعات أقل تكراراً.",
  "يتحول لآسيكلوفير فيثبط بوليميراز DNA الفيروسي وينهي استطالة السلسلة بعد فسفرته بفيروسياً.",
  "الهربس النطاقي (الحزام الناري)، الهربس التناسلي علاجاً وقمعاً، الهربس الفموي، الوقاية من الفيروس المضخم للخلايا بعد الزراعة مختارة.",
  "النطاقي: 1 غ ثلاث مرات يومياً 7 أيام؛ التناسلي الأول: 500 ملغ مرتين 10 أيام؛ القمع: 500 ملغ يومياً.",
  "البروبنسيد والسيميتيدين يرفعان مستواه؛ يزيد سمية الكلى مع الأدوية السامة للكلى.",
  "اشرب ماء كثيراً (بلورات كلوية)؛ صداع وغثيان؛ يعدل في القصور الكلوي؛ أعراض عصبية عند مرضى الكلى.",
  "مسموح عند الحاجة",
  [p("Valtrex", "500 mg", "Tablet", "GSK", "United Kingdom", "NATCO – ناتكو"),
   p("Valacyclovir", "500 mg", "Tablet", "Multiple", "India", "يحتاج توثيق من الإدارة")])

