  "يتحول لمستقلبات تثبط ثيميديلات سينثيز وتندمج في RNA وDNA فتوقف انقسام الخلايا.",
  "سرطان القولون والمستقيم والمعدة والثدي والبنكرياس، سرطان الجلد السطحي وسماك الجلد موضعياً بكريم.",
