e("emergency", "Inotropes", "مقويات التقلص القلبي", "Dobutamine", "دوبوتامين", "C01CA07",
  "مقوٍ للتقلص القلبي في صدمة القلب وفشل القلب الحاد منخفض الناتج.",
  "منبه انتقائي نسبياً لبيتا 1 فيزيد التقلص القلبي والناتج مع أثر وعائي معتدل.",
  "فشل القلب الحاد وصدمة القلب مع ضغط مقبول، دعم الناتج القلبي بعد الجراحة القلبية.",
  "2.5–10 مكغ/كغ/دقيقة تسريباً وريدياً بمضخة مع مراقبة الضغط والنبض والإدرار (حد أقصى 20 مكغ/كغ/دقيقة).",
  "حاصرات بيتا تعاكس أثره؛ الأدوية المطيلة لـQT تزيد خطر اضطراب النظم.",
  "تسرع قلب واضطراب نظم وارتفاع ضغط؛ لا يعطى في انسداد المخرج البطيني؛ عناية مركزة بمراقبة مستمرة.",
  "طوارئ – عناية مركزة",
  [p("Dobutamine", "250 mg/5ml", "Ampoule", "Multiple", "Egypt", "عناية مركزة – مستشفى"),
   p("Dobutrex", "250 mg/20ml", "Vial", "Eli Lilly", "United Kingdom", "عناية مركزة – مستشفى")])
e("emergency", "Anaesthetics (Emergency)", "مخدرات الطوارئ", "Ketamine Injection", "كيتامين حقن", "N01AX03",
  "مخدر انفصالي يحافظ على التنفس والضغط — مثالي للتسكين الإجرائي والطوارئ.",
  "يحصر مستقبلات NMDA فيسبب تخديراً انفصالياً مع تسكين عميق ونساوة دون تثبيط تنفسي مهم.",
  "التسكين الإجرائي (رد خلع، تقطيب، تغيير ضماد الحروق)، تحريض التخدير في الصدمة والربو الشديد، ألم حاد مقاوم.",
  "تسكين إجرائي: 0.5–1 ملغ/كغ وريدياً ببطء أو 3–4 ملغ/كغ عضلياً؛ تحريض تخدير: 1–2 ملغ/كغ وريدياً.",
  "البنزوديازيبينات تقلل الهلوسة الانبثاقية؛ الثيوفيلين يزيد خطر تشنج.",
  "هلوسة وأحلام مزعجة انبثاقية (غطها بميدازولام)؛ لعاب غزير (أضف أتروبين)؛ يرفع الضغط داخل الجمجمة والعين.",
  "بقرار تخدير/طوارئ",
  [p("Ketamine", "50 mg/ml", "Vial", "Multiple", "Egypt", "طوارئ وتخدير – مستشفى"),
   p("Ketalar", "100 mg/ml", "Vial", "Pfizer/Parke-Davis", "France", "طوارئ وتخدير – مستشفى")])
e("emergency", "IV Fluids", "محاليل وريدية", "Normal Saline 0.9% (NaCl)", "محلول ملحي 0.9%", "B05BB01",
  "محلول الإنعاش الأساسي في الصدمة والجفاف والحماض وفقد الدم.",
  "يعوض الحجم داخل الأوعية ويحافظ على الضغط الاسموزي دون أن يستقلب.",
  "الصدمة بنقص الحجم، الجفاف الشديد، غسل الأوعية وإعطاء الأدوية، الحروق، مع نقل الدم.",
  "500–1000 مل بسرعة في الصدمة مع إعادة التقييم، أو حسب خطة الإماهة (البالغ 25–30 مل/كغ/يوم صيانة).",
  "لا توجد تداخلات دوائية مهمة؛ يغير تركيز بعض الأدوية في المحلول الوريدي.",
  "فرط حمل السوائل وفرط كلور وحماض استقلابي فرط كلوري عند الإكثار؛ راقب الإدرار والتهوية والرئة.",
  "يستخدم بحسب الحالة",
  [p("Normal Saline", "500 ml", "IV Bag", "Multiple", "Egypt", "مستشفيات وصيدليات"),
   p("Normal Saline", "1000 ml", "IV Bag", "Multiple", "Saudi Arabia", "مستشفيات وصيدليات")])
e("emergency", "IV Fluids", "محاليل وريدية", "Ringer Lactate (Hartmann)", "رينجر لاكتات", "B05BB01",
  "محلول متوازن قريب من البلازما للإنعاش والحروق والجراحة.",
  "يعوض الحجم والكهارل، واللاكتات تتحول لبيكربونات في الكبد فتعطي أثراً قلوياً خفيفاً.",
  "الإنعاش في الصدمة والحروق والجراحة، الجفاف مع حماض خفيف، بديل للملحي عند خطر فرط الكلور.",
  "500–1000 مل حسب حالة الدورة الدموية مع إعادة التقييم المستمر.",
  "لا يخلط مع السيفترياكسون (ترسب كالسيوم عند الرضع)؛ يتداخل مع الأدوية القلوية.",
  "محتواه من البوتاسيوم منخفض لكنه يستخدم بحذر في فرط بوتاسيوم شديد؛ لا يعالج الحماض الشديد وحده.",
  "يستخدم بحسب الحالة",
  [p("Ringer Lactate", "500 ml", "IV Bag", "Multiple", "Egypt", "مستشفيات وصيدليات"),
   p("Hartmann Solution", "1000 ml", "IV Bag", "Multiple", "United Kingdom", "مستشفيات وصيدليات")])
e("emergency", "IV Fluids", "محاليل وريدية", "Dextrose 5% / 50%", "دكستروز 5% و50%", "B05BA03",
  "محلول سكري للإنعاش في هبوط السكر وتوفير ماء حر.",
  "يمد بالغلوكوز مباشرة لتصحيح نقص السكر ويوفر ماء حراً بعد استقلاب السكر.",
  "هبوط سكر الدم العرضي (50% وريدياً)، إماهة مع نقص صوديوم مختار، ضمن محاليل الإنسولين في فرط بوتاسيوم.",
  "هبوط سكر: 25–50 مل من 50% وريدياً ثم تسريب 5 أو 10% مع إعادة فحص السكر.",
  "الإنسولين ضروري في فرط بوتاسيوم؛ راقب الصوديوم والبوتاسيوم والفوسفات.",
  "50% مهيج للأوردة الصغيرة (يفضل خط مركزي أو تخفيفه)؛ فرط سكر وذمة دماغية عند تصحيح نقص صوديوم بسرعة.",
  "يستخدم بحسب الحالة",
  [p("Dextrose 5%", "500 ml", "IV Bag", "Multiple", "Egypt", "مستشفيات وصيدليات"),
   p("Dextrose 50%", "50 ml", "Ampoule/Syringe", "Multiple", "Egypt", "طوارئ – مستشفى")])

